import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { motion } from 'framer-motion';
import { 
  FaMapMarkedAlt, 
  FaLandmark, 
  FaShoppingCart, 
  FaExternalLinkAlt,
  FaSignOutAlt,
  FaUser
} from 'react-icons/fa';
import './Dashboard.css';

const modules = [
  {
    id: 1,
    title: 'Smart Tourism',
    description: 'Explore Nilgiris with AR navigation',
    icon: FaMapMarkedAlt,
    color: '#2E7D32',
    gradient: 'linear-gradient(135deg, #2E7D32 0%, #66BB6A 100%)',
    path: '/smart-tourism',
    image: 'https://images.unsplash.com/photo-1587474260584-136574528ed5?w=600'
  },
  {
    id: 2,
    title: 'Tribal Heritage & Culture',
    description: 'Discover 6 tribal communities',
    icon: FaLandmark,
    color: '#FF6B35',
    gradient: 'linear-gradient(135deg, #FF6B35 0%, #FFB74D 100%)',
    path: '/tribal-heritage',
    image: 'https://images.unsplash.com/photo-1533105079780-92b9be482077?w=600'
  },
  {
    id: 3,
    title: 'Tribal Products',
    description: 'Shop authentic handmade items',
    icon: FaShoppingCart,
    color: '#1976D2',
    gradient: 'linear-gradient(135deg, #1976D2 0%, #64B5F6 100%)',
    path: '/tribal-products',
    image: 'https://images.unsplash.com/photo-1472851294608-415105022050?w=600'
  },
  {
    id: 4,
    title: 'Badaga Language',
    description: 'Learn Badaga language resources',
    icon: FaExternalLinkAlt,
    color: '#7B1FA2',
    gradient: 'linear-gradient(135deg, #7B1FA2 0%, #BA68C8 100%)',
    path: '/badaga-link',
    image: 'https://images.unsplash.com/photo-1543269865-cbf427effbad?w=600'
  }
];

function Dashboard() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const handleModuleClick = (path) => {
    navigate(path);
  };

  return (
    <div className="dashboard-container">
      {/* Header */}
      <motion.header
        className="dashboard-header"
        initial={{ y: -50, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ duration: 0.5 }}
      >
        <div className="header-content">
          <div className="header-left">
            <h1 className="app-title">🏔️ AR Smart Tourism</h1>
            <p className="welcome-text">Welcome to Nilgiris Heritage App</p>
          </div>
          <div className="header-right">
            <div className="user-info">
              <FaUser className="user-icon" />
              <span className="user-email">{user?.email}</span>
            </div>
            <button className="logout-button" onClick={logout}>
              <FaSignOutAlt /> Logout
            </button>
          </div>
        </div>
      </motion.header>

      {/* Main Content */}
      <main className="dashboard-main">
        <motion.div
          className="modules-grid"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.6, delay: 0.2 }}
        >
          {modules.map((module, index) => (
            <motion.div
              key={module.id}
              className="module-card"
              initial={{ opacity: 0, y: 50 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: 0.1 * index }}
              whileHover={{ scale: 1.05, rotateY: 5 }}
              whileTap={{ scale: 0.98 }}
              onClick={() => handleModuleClick(module.path)}
              style={{ cursor: 'pointer' }}
            >
              <div
                className="module-image"
                style={{ backgroundImage: `url(${module.image})` }}
              >
                <div className="image-overlay"></div>
              </div>
              <div className="module-content">
                <div
                  className="module-icon-wrapper"
                  style={{ background: module.gradient }}
                >
                  <module.icon size={40} color="white" />
                </div>
                <h3 className="module-title">{module.title}</h3>
                <p className="module-description">{module.description}</p>
                <div className="module-arrow">
                  <span>Explore</span> →
                </div>
              </div>
            </motion.div>
          ))}
        </motion.div>
      </main>

      {/* Footer */}
      <footer className="dashboard-footer">
        <p>🌿 AR Smart Tourism & Heritage App | Nilgiris District, Tamil Nadu</p>
        <p>Developed with ❤️ for preserving tribal culture</p>
      </footer>
    </div>
  );
}

export default Dashboard;
